PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','examiner','student')),contact TEXT,department TEXT,status TEXT NOT NULL DEFAULT 'Active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courses (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'Active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS examinations (id INTEGER PRIMARY KEY AUTOINCREMENT,course_id INTEGER NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,duration INTEGER NOT NULL,max_marks REAL NOT NULL,slot_start TEXT,slot_end TEXT,booking_start TEXT,booking_end TEXT,status TEXT NOT NULL DEFAULT 'Draft',instructions TEXT,published INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE IF NOT EXISTS rubrics (id INTEGER PRIMARY KEY AUTOINCREMENT,examination_id INTEGER NOT NULL,criterion TEXT NOT NULL,max_marks REAL NOT NULL,weightage REAL NOT NULL DEFAULT 100,description TEXT,FOREIGN KEY(examination_id) REFERENCES examinations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS slots (id INTEGER PRIMARY KEY AUTOINCREMENT,examination_id INTEGER NOT NULL,examiner_id INTEGER NOT NULL,date TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,capacity INTEGER NOT NULL,available INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',meeting_link TEXT,FOREIGN KEY(examination_id) REFERENCES examinations(id),FOREIGN KEY(examiner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,slot_id INTEGER NOT NULL,booking_date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL DEFAULT 'Booked',FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(slot_id) REFERENCES slots(id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_booking ON bookings(student_id,slot_id) WHERE status='Booked';
CREATE TABLE IF NOT EXISTS evaluations (id INTEGER PRIMARY KEY AUTOINCREMENT,booking_id INTEGER UNIQUE NOT NULL,student_id INTEGER NOT NULL,examiner_id INTEGER NOT NULL,total_marks REAL NOT NULL,remarks TEXT,evaluation_date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL DEFAULT 'Submitted',FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS evaluation_details (id INTEGER PRIMARY KEY AUTOINCREMENT,evaluation_id INTEGER NOT NULL,rubric_id INTEGER NOT NULL,marks REAL NOT NULL,comments TEXT,FOREIGN KEY(evaluation_id) REFERENCES evaluations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS jobs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,type TEXT NOT NULL,status TEXT NOT NULL,filename TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,title TEXT NOT NULL,message TEXT NOT NULL,read INTEGER DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id INTEGER,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS exam_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT,examination_id INTEGER NOT NULL,examiner_id INTEGER NOT NULL,assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(examination_id,examiner_id),FOREIGN KEY(examination_id) REFERENCES examinations(id) ON DELETE CASCADE,FOREIGN KEY(examiner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS booking_history (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 booking_id INTEGER NOT NULL,
 actor_user_id INTEGER,
 action TEXT NOT NULL,
 old_slot_id INTEGER,
 new_slot_id INTEGER,
 details TEXT,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(booking_id) REFERENCES bookings(id),
 FOREIGN KEY(actor_user_id) REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS idx_slots_exam ON slots(examination_id);
CREATE INDEX IF NOT EXISTS idx_bookings_student ON bookings(student_id);
CREATE INDEX IF NOT EXISTS idx_booking_history_booking ON booking_history(booking_id,created_at);

